<template>
  <section class="page">
    <header class="page__header">
      <div><h1 class="page__title">设备管理</h1><p class="page__desc">管理门禁设备和车场设备</p></div>
      <button class="btn btn--primary btn--sm" type="button" @click="openCreate"><span class="material-icons-outlined">add</span>新增设备</button>
    </header>

    <section class="card">
      <div class="card__body card__body--filters">
        <div class="toolbar">
          <input v-model.trim="filters.keyword" class="input" type="search" placeholder="编号 / 名称 / 品牌 / 位置" @keyup.enter="search">
          <select v-model="filters.type" class="select" aria-label="设备类型"><option value="">全部类型</option><option v-for="type in types" :key="type" :value="type">{{ type }}</option></select>
          <select v-model="filters.status" class="select" aria-label="设备状态"><option value="">全部状态</option><option value="1">在线</option><option value="0">离线</option></select>
          <div class="toolbar__right"><button class="btn btn--soft btn--sm" type="button" @click="search"><span class="material-icons-outlined">search</span>搜索</button><button class="btn btn--ghost btn--sm" type="button" @click="resetFilters"><span class="material-icons-outlined">restart_alt</span>重置</button></div>
        </div>
      </div>
      <div v-if="loading" class="state">正在加载设备数据...</div>
      <div v-else-if="errorMessage" class="state state--error">{{ errorMessage }}</div>
      <div v-else class="table-wrap">
        <table class="table">
          <thead><tr><th>编号</th><th>设备编码</th><th>设备名称</th><th>设备类型</th><th>品牌</th><th>型号</th><th>安装位置</th><th>安装时间</th><th>最后在线</th><th>状态</th><th>备注</th><th class="actions-cell">操作</th></tr></thead>
          <tbody>
            <tr v-for="device in pagedDevices" :key="device.id">
              <td>{{ String(device.id).padStart(4, "0") }}</td><td><strong class="device-code">{{ device.code }}</strong></td><td>{{ device.name }}</td>
              <td><span class="tag" :class="device.type === '门禁设备' ? 'tag--blue' : 'tag--orange'">{{ device.type }}</span></td>
              <td><span class="tag" :class="device.brand === 'Hikvision' ? 'tag--blue' : 'tag--green'">{{ device.brand }}</span></td>
              <td class="text-sub">{{ device.model || "-" }}</td><td>{{ device.location || "-" }}</td><td class="text-sub nowrap">{{ device.installDate || "-" }}</td><td class="text-sub nowrap">{{ device.lastOnline || "-" }}</td>
              <td><span class="tag" :class="statusClass(device.status)">{{ statusLabel(device.status) }}</span></td><td class="remark-cell text-sub" :title="device.remark || ''">{{ device.remark || "-" }}</td>
              <td class="actions-cell"><button class="row-act" type="button" title="编辑" @click="openEdit(device)"><span class="material-icons-outlined">edit</span></button><button class="row-act row-act--danger" type="button" title="删除" @click="removeDevice(device)"><span class="material-icons-outlined">delete</span></button></td>
            </tr>
            <tr v-if="pagedDevices.length === 0"><td class="empty" colspan="12">暂无数据</td></tr>
          </tbody>
        </table>
      </div>
      <footer v-if="!loading && !errorMessage" class="pagination"><span class="pagination__info">共 {{ deviceTotal }} 条</span><button class="page-btn" type="button" title="上一页" :disabled="page <= 1" @click="changePage(page - 1)"><span class="material-icons-outlined">chevron_left</span></button><button v-for="pageNumber in pageNumbers" :key="pageNumber" class="page-btn" :class="{ active: pageNumber === page }" type="button" @click="changePage(pageNumber)">{{ pageNumber }}</button><button class="page-btn" type="button" title="下一页" :disabled="page >= totalPages" @click="changePage(page + 1)"><span class="material-icons-outlined">chevron_right</span></button></footer>
    </section>

    <div v-if="editorVisible" class="modal-mask" @click.self="editorVisible = false">
      <form class="modal modal--xl" @submit.prevent="saveDevice">
        <header class="modal__head"><h2 class="modal__title">{{ editingId ? "编辑设备" : "新增设备" }}</h2><button class="icon-button" type="button" title="关闭" @click="editorVisible = false"><span class="material-icons-outlined">close</span></button></header>
        <div class="modal__body">
          <div class="form-grid">
            <label class="field"><span class="field__label">设备编码<span class="req">*</span></span><input v-model.trim="form.code" class="input" required placeholder="如：AC-001"></label><label class="field"><span class="field__label">设备名称<span class="req">*</span></span><input v-model.trim="form.name" class="input" required></label>
            <label class="field"><span class="field__label">设备类型</span><select v-model="form.type" class="select"><option>门禁设备</option><option>车场设备</option></select></label><label class="field"><span class="field__label">品牌</span><select v-model="form.brand" class="select"><option value="Hikvision">Hikvision（海康威视）</option><option value="Keytop">Keytop（科拓）</option></select></label>
            <label class="field"><span class="field__label">安装位置</span><input v-model.trim="form.location" class="input"></label><label class="field"><span class="field__label">安装时间</span><input v-model="form.installDate" class="input" type="date"></label>
          </div>
          <section class="perm-section"><header class="perm-section__head"><h3 class="perm-section__title">连接配置</h3></header><p class="connection-hint">根据品牌类型填写对应的连接参数，保存后系统将连接平台获取设备型号、状态等信息</p><div class="form-grid">
            <template v-if="form.brand === 'Hikvision'"><label class="field full"><span class="field__label">Host（IP / Domain）</span><input v-model.trim="form.host" class="input" placeholder="https://api2.hik-cloud.com 或 192.168.1.201"></label><label class="field"><span class="field__label">Username</span><input v-model.trim="form.username" class="input" placeholder="设备用户名"></label><label class="field"><span class="field__label">Password</span><input v-model="form.password" class="input" type="password" placeholder="设备密码"></label></template>
            <template v-else><label class="field"><span class="field__label">AppId</span><input v-model.trim="form.appId" class="input" placeholder="科拓AppId"></label><label class="field"><span class="field__label">ParkId</span><input v-model.trim="form.parkId" class="input" placeholder="科拓车场ID"></label><label class="field full"><span class="field__label">AppSecret</span><input v-model="form.appSecret" class="input" type="password" placeholder="科拓AppSecret"></label></template>
          </div></section>
          <div class="form-grid form-grid--remark"><label class="field full"><span class="field__label">备注</span><input v-model.trim="form.remark" class="input"></label></div><p v-if="formError" class="form-error">{{ formError }}</p>
        </div>
        <footer class="modal__foot"><button class="btn btn--ghost" type="button" @click="editorVisible = false">取消</button><button class="btn btn--primary" type="submit" :disabled="saving">{{ saving ? "保存中..." : "保存" }}</button></footer>
      </form>
    </div>
    <div v-if="toast" class="toast" :class="`toast--${toast.type}`"><span class="material-icons-outlined">{{ toast.type === 'error' ? 'error_outline' : 'check_circle_outline' }}</span>{{ toast.text }}</div>
  </section>
</template>

<script setup lang="ts">
interface Device { id: number; code: string; name: string; type: string; brand: string; model?: string | null; location?: string | null; ip?: string | null; installDate?: string | null; status: number | null; lastOnline?: string | null; remark?: string | null }
interface DeviceList { items: Device[]; total: number }
interface DeviceForm { code: string; name: string; type: string; brand: string; location: string; installDate: string; host: string; username: string; password: string; appId: string; parkId: string; appSecret: string; remark: string; model: string; status: number | null; lastOnline: string }
type Toast = { text: string; type: "success" | "error" };

const http = useHttp();
const pageSize = 8; const devices = ref<Device[]>([]); const deviceTotal = ref(0); const loading = ref(true); const saving = ref(false); const errorMessage = ref(""); const formError = ref(""); const page = ref(1); const editingId = ref<number | null>(null); const editorVisible = ref(false); const toast = ref<Toast | null>(null);
const filters = reactive({ keyword: "", type: "", status: "" });
const form = reactive<DeviceForm>({ code: "", name: "", type: "门禁设备", brand: "Hikvision", location: "", installDate: "", host: "", username: "", password: "", appId: "", parkId: "", appSecret: "", remark: "", model: "", status: null, lastOnline: "" });
const types = computed(() => [...new Set(devices.value.map((device) => device.type).filter(Boolean))]);
const filteredDevices = computed(() => { const keyword = filters.keyword.toLowerCase(); return devices.value.filter((device) => (!keyword || [device.code, device.name, device.brand, device.location].some((value) => (value || "").toLowerCase().includes(keyword))) && (!filters.type || device.type === filters.type) && (filters.status === "" || device.status === Number(filters.status))); });
const totalPages = computed(() => Math.max(1, Math.ceil(deviceTotal.value / pageSize))); const pageNumbers = computed(() => Array.from({ length: totalPages.value }, (_, index) => index + 1).slice(Math.max(0, page.value - 3), page.value + 2)); const pagedDevices = computed(() => devices.value);
function statusLabel(status: number | null) { return status === 1 ? "在线" : status === 0 ? "离线" : "未连接"; } function statusClass(status: number | null) { return status === 1 ? "tag--green" : status === 0 ? "tag--red" : "tag--gray"; } function modelFor(brand: string) { const models = brand === "Hikvision" ? ["DS-K1T642", "DS-K1T201", "DS-K1T801", "DS-2CD2T86"] : ["KT-CR200", "KT-GT300", "KT-LS100", "KT-CP50"]; return models[Math.floor(Math.random() * models.length)]; }
function showToast(text: string, type: Toast["type"]) { toast.value = { text, type }; window.setTimeout(() => { toast.value = null; }, 2800); } function resetForm() { Object.assign(form, { code: "", name: "", type: "门禁设备", brand: "Hikvision", location: "", installDate: "", host: "", username: "", password: "", appId: "", parkId: "", appSecret: "", remark: "", model: "", status: null, lastOnline: "" }); } async function search() { page.value = 1; await loadDevices(); } async function resetFilters() { Object.assign(filters, { keyword: "", type: "", status: "" }); page.value = 1; await loadDevices(); } function changePage(nextPage: number) { if (nextPage < 1 || nextPage > totalPages.value) return; page.value = nextPage; void loadDevices(); }
async function loadDevices() { loading.value = true; errorMessage.value = ""; try { const result = await http.get<DeviceList>("/devices", { keyword: filters.keyword || undefined, type: filters.type || undefined, status: filters.status === "" ? undefined : Number(filters.status), page: page.value, pageSize }); devices.value = result.items || []; deviceTotal.value = result.total || 0; if (page.value > totalPages.value) page.value = totalPages.value; } catch (error) { errorMessage.value = (error as { statusMessage?: string }).statusMessage || "设备数据加载失败"; } finally { loading.value = false; } }
function openCreate() { editingId.value = null; formError.value = ""; resetForm(); editorVisible.value = true; } function openEdit(device: Device) { editingId.value = device.id; formError.value = ""; Object.assign(form, { code: device.code, name: device.name, type: device.type, brand: device.brand, location: device.location || "", installDate: device.installDate || "", host: device.ip || "", username: "", password: "", appId: "", parkId: "", appSecret: "", remark: device.remark || "", model: device.model || "", status: device.status, lastOnline: device.lastOnline || "" }); editorVisible.value = true; }
async function saveDevice() { if (!form.code || !form.name) { formError.value = "编码和名称不能为空"; return; } saving.value = true; formError.value = ""; const isNew = editingId.value === null; const status = form.status ?? 0; const payload = { code: form.code, name: form.name, type: form.type, brand: form.brand, model: form.model || modelFor(form.brand), location: form.location || "-", ip: form.host || "-", installDate: form.installDate || "1970-01-01", status }; try { if (editingId.value) await http.put(`/devices/${editingId.value}`, payload, { payloadMode: "json" }); else await http.post("/devices", payload, { payloadMode: "json" }); editorVisible.value = false; await loadDevices(); showToast(isNew ? "新增成功" : "修改成功", "success"); } catch (error) { formError.value = (error as { statusMessage?: string }).statusMessage || "保存失败"; } finally { saving.value = false; } }
async function removeDevice(device: Device) { if (!window.confirm("确认删除该设备？")) return; try { await http.delete(`/devices/${device.id}`); await loadDevices(); showToast("删除成功", "success"); } catch (error) { showToast((error as { statusMessage?: string }).statusMessage || "删除失败", "error"); } }
onMounted(loadDevices);
</script>

<style scoped>
.page{min-height:100%;padding:24px}.page__header{align-items:center;display:flex;flex-wrap:wrap;gap:12px;justify-content:space-between;margin-bottom:20px}.page__title{color:var(--text);font-size:18px;font-weight:600;margin:0}.page__desc{color:var(--text-sub);font-size:13px;margin:2px 0 0}.card{background:var(--card);border:1px solid var(--border-strong);border-radius:8px;overflow:hidden}.card__body{padding:18px}.card__body--filters{padding-bottom:0}.toolbar{align-items:center;display:flex;flex-wrap:wrap;gap:10px;margin-bottom:14px}.toolbar .input,.toolbar .select{min-width:140px;width:auto}.toolbar__right{display:flex;gap:6px;margin-left:auto}.input,.select{background:var(--card);border:1px solid var(--border-strong);border-radius:6px;box-sizing:border-box;color:var(--text);font:inherit;font-size:13px;height:34px;outline:none;padding:0 10px;width:100%}.input:focus,.select:focus{border-color:var(--primary);box-shadow:0 0 0 2px var(--primary-soft)}.btn{align-items:center;border:1px solid transparent;border-radius:6px;cursor:pointer;display:inline-flex;font:inherit;font-size:13px;font-weight:500;gap:5px;height:32px;justify-content:center;padding:0 12px;white-space:nowrap}.btn .material-icons-outlined{font-size:16px}.btn--primary{background:var(--primary);color:#fff}.btn--soft{background:var(--primary-soft);color:var(--primary)}.btn--ghost{background:var(--card);border-color:var(--border-strong);color:var(--text-sub)}.btn--sm{font-size:12px;height:28px;padding:0 10px}.btn:disabled{cursor:wait;opacity:.6}.table-wrap{overflow-x:auto}.table{border-collapse:collapse;font-size:13px;min-width:1250px;width:100%}.table th{background:var(--bg);border-bottom:1px solid var(--border);color:var(--text-mute);font-size:12px;font-weight:500;padding:10px 16px;text-align:left;white-space:nowrap}.table td{border-bottom:1px solid var(--border);color:var(--text);padding:11px 16px;white-space:nowrap}.table tbody tr:hover{background:var(--bg)}.device-code{color:var(--primary)}.text-sub{color:var(--text-sub)!important}.nowrap{white-space:nowrap}.remark-cell{max-width:100px;overflow:hidden;text-overflow:ellipsis}.actions-cell{text-align:right!important}.tag{align-items:center;border-radius:4px;display:inline-flex;font-size:12px;font-weight:500;gap:4px;line-height:1.5;padding:2px 8px}.tag:before{background:currentcolor;border-radius:50%;content:"";height:5px;width:5px}.tag--green{background:#ecfdf5;color:#059669}.tag--red{background:#fef2f2;color:#dc2626}.tag--blue{background:var(--primary-soft);color:var(--primary)}.tag--orange{background:#fff7ed;color:#ea580c}.tag--gray{background:#f4f4f5;color:var(--text-sub)}.row-act,.icon-button{align-items:center;background:transparent;border:0;border-radius:5px;color:var(--text-mute);cursor:pointer;display:inline-flex;height:26px;justify-content:center;margin:0 1px;width:26px}.row-act:hover{background:var(--bg);color:var(--text)}.row-act--danger:hover{background:#fef2f2;color:var(--red)}.row-act .material-icons-outlined,.icon-button .material-icons-outlined{font-size:16px}.state,.empty{color:var(--text-mute);padding:40px;text-align:center}.state--error,.form-error{color:var(--red)}.pagination{align-items:center;border-top:1px solid var(--border);display:flex;flex-wrap:wrap;gap:4px;justify-content:flex-end;padding:12px 16px}.pagination__info{color:var(--text-sub);font-size:12px;margin-right:auto}.page-btn{align-items:center;background:var(--card);border:1px solid var(--border-strong);border-radius:5px;color:var(--text-sub);cursor:pointer;display:flex;font-size:12px;height:28px;justify-content:center;min-width:28px;padding:0 6px}.page-btn.active{background:var(--primary);border-color:var(--primary);color:#fff}.page-btn:disabled{cursor:not-allowed;opacity:.4}.page-btn .material-icons-outlined{font-size:16px}.modal-mask{align-items:center;background:#0006;display:flex;inset:0;justify-content:center;position:fixed;z-index:100}.modal{background:var(--card);border:1px solid var(--border-strong);border-radius:8px;display:flex;flex-direction:column;max-height:calc(100vh - 40px);max-width:calc(100vw - 40px);overflow:hidden;width:640px}.modal--xl{width:860px}.modal__head{align-items:center;border-bottom:1px solid var(--border);display:flex;justify-content:space-between;padding:14px 20px}.modal__title{color:var(--text);font-size:15px;font-weight:600;margin:0}.modal__body{overflow-y:auto;padding:20px}.modal__foot{border-top:1px solid var(--border);display:flex;gap:8px;justify-content:flex-end;padding:12px 20px}.form-grid{display:grid;gap:0 16px;grid-template-columns:1fr 1fr}.form-grid .full{grid-column:1/-1}.form-grid--remark{margin-top:8px}.field{display:block;margin-bottom:14px}.field__label{color:var(--text-sub);display:block;font-size:12px;font-weight:500;margin-bottom:5px}.req{color:var(--red);margin-left:2px}.perm-section{margin-top:8px;padding-top:16px;border-top:1px dashed var(--border-strong)}.perm-section__head{align-items:center;display:flex;flex-wrap:wrap;gap:8px;justify-content:space-between;margin-bottom:12px}.perm-section__title{align-items:center;color:var(--text);display:flex;font-size:14px;font-weight:600;gap:6px;margin:0}.perm-section__title:before{background:var(--primary);border-radius:2px;content:"";height:14px;width:3px}.connection-hint{color:var(--text-sub);font-size:12px;margin:0 0 10px}.toast{align-items:center;background:var(--card);border:1px solid var(--border-strong);border-left:3px solid var(--primary);border-radius:6px;display:flex;font-size:13px;gap:8px;min-width:220px;padding:10px 14px;position:fixed;right:16px;top:16px;z-index:200}.toast--success{border-left-color:#059669}.toast--success .material-icons-outlined{color:#059669}.toast--error{border-left-color:var(--red)}.toast--error .material-icons-outlined{color:var(--red)}@media(max-width:768px){.page{padding:16px}.form-grid{grid-template-columns:1fr}.form-grid .full{grid-column:auto}.toolbar__right{margin-left:0}.modal__body{padding:16px}}@media(max-width:480px){.toolbar .input,.toolbar .select,.toolbar__right{width:100%}.toolbar__right .btn{flex:1}}
</style>
